{ config, lib, ... }:

let
  hostSecretsFile = ../../secrets/s145/secrets.yaml;
  hasHostSecretsFile = builtins.pathExists hostSecretsFile;
  tailscaleSecretsFile = ../../secrets/tailscale/secrets.yaml;
  hasTailscaleSecretsFile = builtins.pathExists tailscaleSecretsFile;
  clusterSecretsFile = ../../secrets/k3s/secrets.yaml;
  hasClusterSecretsFile = builtins.pathExists clusterSecretsFile;
in
{
  sops = {
    age.keyFile = "/var/lib/sops-nix/key.txt";
    age.generateKey = false;
    age.sshKeyPaths = [ ];

    defaultSopsFormat = "yaml";

    secrets = lib.mkMerge [
      (lib.mkIf hasTailscaleSecretsFile {
        "tailscale-auth-key" = {
          sopsFile = tailscaleSecretsFile;
        };
      })

      (lib.mkIf hasClusterSecretsFile {
        # Shared k3s cluster token used by the server (this host) and worker agents.
        "k3s-token" = {
          sopsFile = clusterSecretsFile;
        };
      })

      (lib.mkIf hasHostSecretsFile {
        "wifi-ssid" = {
          sopsFile = hostSecretsFile;
        };

        "wifi-psk" = {
          sopsFile = hostSecretsFile;
        };

        # Scoped Cloudflare API token (Zone:DNS:Edit + Zone:Zone:Read).
        # Consumed by Traefik's ACME DNS-01 challenge via a k8s Secret.
        "cloudflare-dns-api-token" = {
          sopsFile = hostSecretsFile;
        };
      })
    ];

    templates = lib.mkIf hasHostSecretsFile {
      "s145-network.env".content = ''
        WIFI_SSID=${config.sops.placeholder."wifi-ssid"}
        WIFI_PSK=${config.sops.placeholder."wifi-psk"}
      '';

      # Rendered straight into k3s's auto-deploy manifests dir so the
      # token never lives on disk as plain text outside /run.
      "traefik-cloudflare-secret.yaml" = {
        path = "/var/lib/rancher/k3s/server/manifests/traefik-cloudflare-secret.yaml";
        mode = "0600";
        owner = "root";
        group = "root";
        content = ''
          apiVersion: v1
          kind: Secret
          metadata:
            name: traefik-cloudflare
            namespace: kube-system
          type: Opaque
          stringData:
            CF_DNS_API_TOKEN: ${config.sops.placeholder."cloudflare-dns-api-token"}
        '';
      };
    };
  };
}

# hosts/s145/configuration.nix — standalone server (x86_64, WiFi)
#
# Host-specific settings only. Shared config comes from profiles.
{ config, lib, ... }:

let
  hostSecretsFile = ../../secrets/s145/secrets.yaml;
  hasHostSecretsFile = builtins.pathExists hostSecretsFile;
  hasTailscaleSecretsFile = builtins.pathExists ../../secrets/tailscale/secrets.yaml;
in
{
  imports = [
    ../../profiles/base.nix
    ../../profiles/server.nix
    ../../profiles/tailscale.nix
    ../../profiles/k3s-server.nix
    ../../profiles/smartd.nix
    ./disko-config.nix
    ./samba.nix
    ./sops.nix
    ./traefik.nix
  ];

  networking.hostName = "s145";

  # k3s — host-specific identity. s145 is the sole control-plane; the
  # Oracle free-tier hosts join as disposable agents.
  services.k3s.nodeName = "s145";
  services.k3s.nodeIP = "100.69.231.117";

  # Boot — systemd-boot (override GRUB from server.nix)
  boot.loader.grub.enable = lib.mkForce false;
  boot.loader.systemd-boot.enable = lib.mkForce true;
  boot.loader.efi.canTouchEfiVariables = lib.mkForce true;
  boot.kernelParams = lib.mkForce [ "systemd.gpt_auto=0" ];

  boot.initrd.availableKernelModules = [ "nvme" "xhci_pci" "ahci" "usb_storage" "sd_mod" ];
  boot.kernelModules = [ "kvm-amd" ];

  # 1TB HDD (/dev/sda1, XFS) mounted into duck's home directory.
  # Not managed by disko — pre-existing filesystem with critical data.
  # Identified by UUID so SATA/USB enumeration changes don't break the mount.
  # `nofail` keeps boot resilient if the disk is absent; the empty mountpoint
  # is intentionally left root-owned so writes fail loudly when unmounted
  # rather than silently landing on the root filesystem.
  # In-FS ownership is set once after first mount:
  #   sudo chown duck:users /home/duck/sda
  fileSystems."/home/duck/sda" = {
    device = "/dev/disk/by-uuid/41a4db90-cbd4-490b-a01f-a8925f2b419b";
    fsType = "xfs";
    options = [
      "defaults"
      "noatime" # avoid an HDD write on every read
      "nofail" # don't block boot if the disk is missing
      "x-systemd.device-timeout=30"
      "x-systemd.mount-timeout=30"
    ];
  };

  # Keep server workloads running when the laptop lid is closed.
  services.logind.settings.Login = {
    HandleLidSwitch = "ignore";
    HandleLidSwitchExternalPower = "ignore";
    HandleLidSwitchDocked = "ignore";
  };
  systemd.sleep.settings.Sleep = {
    AllowSuspend = "no";
    AllowHibernation = "no";
    AllowHybridSleep = "no";
    AllowSuspendThenHibernate = "no";
  };

  # Realtek USB WiFi adapter firmware
  hardware.enableRedistributableFirmware = true;

  # WiFi via NetworkManager + SOPS
  networking.networkmanager.ensureProfiles = lib.mkMerge [
    {
      profiles.s145-wired = {
        connection = {
          id = "s145-wired";
          type = "ethernet";
          autoconnect = true;
          autoconnect-priority = 100;
        };
        ipv4.method = "auto";
        ipv6.method = "auto";
      };
    }
    (lib.mkIf hasHostSecretsFile {
      environmentFiles = [
        config.sops.templates."s145-network.env".path
      ];

      profiles.s145-wifi = {
        connection = {
          id = "s145-wifi";
          type = "wifi";
          interface-name = "wlp2s0";
          autoconnect = true;
        };
        wifi = {
          mode = "infrastructure";
          ssid = "$WIFI_SSID";
        };
        wifi-security = {
          key-mgmt = "wpa-psk";
          psk = "$WIFI_PSK";
        };
        ipv4.method = "auto";
        ipv6.method = "auto";
      };
    })
  ];

  # Tailscale — host identity + exit node
  services.tailscale.useRoutingFeatures = "server"; # handles ip_forward sysctls
  services.tailscale.extraUpFlags = lib.mkIf hasTailscaleSecretsFile [
    "--hostname=s145"
    "--accept-dns=false"
  ];
  services.tailscale.extraSetFlags = [
    "--advertise-exit-node"
  ];

  nixpkgs.hostPlatform = lib.mkDefault "x86_64-linux";
  system.stateVersion = "26.05";
}

